/*
 * Synthesis probe for oca_udp_complete_64.
 *
 * Not part of any build. It exists so the wrapper can be pushed through the
 * exact frontend combination the real build uses -- vendor Verilog and the
 * wrapper via read_verilog, our SystemVerilog via read_slang, instantiating
 * the wrapper with no parameter overrides -- because that combination is
 * what the wrapper exists to survive, and a wrapper that only passes
 * read_verilog on its own has not been tested.
 *
 * Every port is carried to the probe's own boundary so nothing is optimised
 * away and the area figures characterise the wrapper rather than what
 * survived constant propagation.
 *
 * From the repository root, with tools/yosys built by
 * scripts/build-toolchain.sh:
 *
 *   timeout 900 tools/yosys/bin/yosys -p "read_verilog \
 *     -Ioca/hw/vendor/verilog-ethernet/rtl \
 *     -Ioca/hw/vendor/verilog-ethernet/lib/axis/rtl \
 *     oca/hw/vendor/verilog-ethernet/rtl/udp_complete_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/ip_complete_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/ip_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/ip_eth_rx_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/ip_eth_tx_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/ip_arb_mux.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/arp.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/arp_cache.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/arp_eth_rx.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/arp_eth_tx.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/eth_arb_mux.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/udp_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/udp_ip_rx_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/udp_ip_tx_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/udp_checksum_gen_64.v \
 *     oca/hw/vendor/verilog-ethernet/rtl/lfsr.v \
 *     oca/hw/vendor/verilog-ethernet/lib/axis/rtl/axis_fifo.v \
 *     oca/hw/vendor/verilog-ethernet/lib/axis/rtl/arbiter.v \
 *     oca/hw/vendor/verilog-ethernet/lib/axis/rtl/priority_encoder.v \
 *     oca/hw/rtl/vendor/oca_udp_complete_64.v; \
 *     read_slang --top oca_udp_complete_64_probe \
 *     oca/hw/rtl/vendor/oca_udp_complete_64_probe.sv; \
 *     hierarchy -check -top oca_udp_complete_64_probe; \
 *     synth_ecp5 -top oca_udp_complete_64_probe; stat"
 */
module oca_udp_complete_64_probe (
    input  logic        clk,
